import { z } from 'zod/v4';

export const mastraPackageSchema = z.object({
  name: z.string(),
  version: z.string(),
});

export const observabilityRuntimeStrategySchema = z.enum([
  'realtime',
  'batch-with-updates',
  'insert-only',
  'event-sourced',
]);

export const observabilityDiscoveryCapabilitiesSchema = z.object({
  entityTypes: z.boolean().describe('GET /observability/discovery/entity-types'),
  entityNames: z.boolean().describe('GET /observability/discovery/entity-names'),
  serviceNames: z.boolean().describe('GET /observability/discovery/service-names'),
  environments: z.boolean().describe('GET /observability/discovery/environments'),
  tags: z.boolean().describe('GET /observability/discovery/tags'),
  metrics: z.boolean().describe('GET /observability/discovery/metric-names, metric-label-keys and metric-label-values'),
});

/**
 * Optional observability APIs the configured observability store can serve.
 * Omitted when no observability store is configured.
 */
export const observabilityStorageCapabilitiesSchema = z.object({
  metrics: z.boolean().describe('Metrics endpoints (/observability/metrics and /observability/metrics/*)'),
  logs: z.boolean().describe('Logs endpoint (GET /observability/logs)'),
  discovery: observabilityDiscoveryCapabilitiesSchema.describe(
    'Filter discovery endpoints. Unsupported discovery routes return empty results.',
  ),
  deltaPolling: z.boolean().describe("Cursor-based `mode: 'delta'` polling on observability list endpoints"),
  traceQuery: z
    .boolean()
    .describe(
      'Advanced trace queries (POST /observability/traces/query). When false, list traces with GET /observability/traces/light instead.',
    ),
  traceQueryAggregatedRoots: z
    .boolean()
    .default(false)
    .describe("Supports explicit `rootSource: 'aggregated'` trace queries"),
  traceQueryTokenSearch: z.boolean().default(false).describe('Token matching across any span in a trace'),
  spanQueryTokenSearch: z.boolean().default(false).describe('Token matching within individual spans'),
  traceAggregateTokenSearch: z.boolean().default(false).describe('Token predicates in trace aggregates'),
  spanAggregateTokenSearch: z.boolean().default(false).describe('Token predicates in span aggregates'),
  traceQueryRootDuration: z.boolean().describe('`durationMs` predicates in trace and thread queries'),
  traceQueryContextIds: z
    .boolean()
    .describe('`runId`, `sessionId`, `userId` and `organizationId` predicates in trace and thread queries'),
  traceQueryContextFields: z
    .boolean()
    .describe('`requestId`, `serviceName` and `experimentId` predicates in trace and thread queries'),
  traceQueryTimeToFirstChunk: z
    .boolean()
    .describe(
      '`timeToFirstChunkMs` in trace and span query results, and predicates on it in trace, thread and span queries',
    ),
  traceQueryRootSpanFields: z
    .boolean()
    .describe('Root span `name` and `spanType` in trace-scope predicates, aggregate `groupBy` and `countDistinct`'),
  traceQueryRootEntityId: z
    .boolean()
    .describe('Root span `entityId` in trace-scope predicates, aggregate `groupBy` and `countDistinct`'),
  traceQueryTimeToFirstChunkSort: z.boolean().describe('Sorting trace and span queries by `timeToFirstChunkMs`'),
  traceQueryTimeToFirstToken: z
    .boolean()
    .describe(
      '`timeToFirstTokenMs` in trace, thread and span query results, and predicates on it in trace, thread and span queries',
    ),
  traceQueryTimeToFirstTokenSort: z.boolean().describe('Sorting trace and span queries by `timeToFirstTokenMs`'),
  traceQueryDiscovery: z
    .boolean()
    .describe('Trace query field discovery (POST /observability/traces/query/fields and /values)'),
  traceQueryTenantScope: z.boolean().describe('Trusted tenant scoping of trace and thread queries'),
  traceAggregate: z
    .boolean()
    .describe(
      'Trace aggregation (POST /observability/traces/aggregate). Unlike `traceQuery`, clients should treat a missing value as unavailable.',
    ),
  spanAggregate: z
    .boolean()
    .describe(
      'Span aggregation (POST /observability/spans/aggregate). Unlike `spanQuery`, clients should treat a missing value as unavailable.',
    ),
  threadQuery: z.boolean().describe('Advanced thread queries (POST /observability/threads/query)'),
  threadQueryRows: z
    .boolean()
    .default(false)
    .describe(
      'Full-history thread rows with activity windows, filters and sorting. Treat a missing value as unavailable.',
    ),
  spanQuery: z.boolean().describe('Span queries (POST /observability/spans/query)'),
  spanQueryDurationSort: z.boolean().default(false).describe('Whether completed spans can be sorted by duration'),
  spanQueryModelProviderSort: z.boolean().default(false).describe('Whether spans can be sorted by model and provider'),
  spanQueryContextFields: z
    .boolean()
    .default(false)
    .describe(
      'Additional identity, context and parent/root entity predicates in span queries. Treat a missing value as unavailable.',
    ),
  spanQueryModelFields: z
    .boolean()
    .default(false)
    .describe(
      '`model` and `provider` predicates in span queries and span aggregates. Treat a missing value as unavailable.',
    ),
  spanAggregateModelDimensions: z
    .boolean()
    .default(false)
    .describe(
      '`model` and `provider` in span aggregate `groupBy` and `countDistinct`. Treat a missing value as unavailable.',
    ),
  aggregateTimeToFirstMeasures: z
    .boolean()
    .default(false)
    .describe(
      '`timeToFirstToken.*` and `timeToFirstChunk.*` measures in trace and span aggregates. Treat a missing value as unavailable.',
    ),
  spanQueryOutcomeFields: z
    .boolean()
    .default(false)
    .describe(
      '`outcome` and `stopReason` predicates in span queries and span aggregates (including `groupBy` and `countDistinct`), and `outcome`, `stopReason` and `stopReasonContext` on span rows. Treat a missing value as unavailable.',
    ),
  traceQueryOutcomeFields: z
    .boolean()
    .default(false)
    .describe(
      "The root span's `outcome` and `stopReason` in trace-scope predicates and trace aggregates, both fields in `spans.some`/`spans.none` predicates and value discovery, and the root span's `outcome`, `stopReason` and `stopReasonContext` on trace rows. Treat a missing value as unavailable.",
    ),
  traceRetentionDays: z
    .number()
    .int()
    .positive()
    .optional()
    .describe(
      'Days of traces the store keeps. Older traces are gone, so clients can stop users from picking dates before them. Omitted when the store does not report a limit.',
    ),
  feedbackReplacement: z.boolean().default(false).describe('Full feedback replacement with PUT'),
  feedback: z
    .boolean()
    .describe(
      'Feedback endpoints (/observability/feedback and /observability/feedback/*). Unsupported feedback routes return 501.',
    ),
});

export const editorSourceSchema = z.enum(['code', 'db']);

export const editorSourceCapabilitiesSchema = z.object({
  source: editorSourceSchema,
  storage: z.enum(['database', 'filesystem', 'source-provider', 'unavailable']),
  provider: z
    .object({
      id: z.string(),
      displayName: z.string(),
    })
    .optional(),
  canSave: z.boolean(),
  canOpenChangeRequest: z.boolean(),
  unavailableReason: z.string().optional(),
});

export const systemPackagesResponseSchema = z.object({
  packages: z.array(mastraPackageSchema),
  isDev: z.boolean(),
  cmsEnabled: z.boolean(),
  /** Whether the default LiveKit connection-details route is registered — not whether credentials or a worker exist. */
  liveKitConnectionRouteEnabled: z.boolean(),
  /** True when the default LiveKit trace recording review route is registered. */
  liveKitRecordingRouteEnabled: z.boolean().optional(),
  /**
   * The editor's configured source, when set. `'code'` swaps Studio's
   * Save/Publish UI for Download JSON + Open PR. `'db'` keeps the standard
   * Save/Publish flow. Omitted when the editor has no explicit source.
   */
  editorSource: editorSourceSchema.optional(),
  editorSourceCapabilities: editorSourceCapabilitiesSchema.optional(),
  observabilityEnabled: z.boolean(),
  storageType: z.string().optional(),
  observabilityStorageType: z.string().optional(),
  observabilityStorageCapabilities: observabilityStorageCapabilitiesSchema.optional(),
  observabilityRuntimeStrategy: observabilityRuntimeStrategySchema.optional(),
});

const jsonSchemaRecordSchema = z.record(z.string(), z.unknown());

export const apiSchemaResponseShapeSchema = z.object({
  kind: z.enum(['array', 'record', 'object-property', 'single', 'unknown']),
  listProperty: z.string().optional(),
  paginationProperty: z.string().optional(),
});

export const apiSchemaManifestRouteSchema = z.object({
  method: z.string(),
  path: z.string(),
  responseType: z.string(),
  pathParamSchema: jsonSchemaRecordSchema.optional(),
  queryParamSchema: jsonSchemaRecordSchema.optional(),
  bodySchema: jsonSchemaRecordSchema.optional(),
  responseSchema: jsonSchemaRecordSchema.optional(),
  responseShape: apiSchemaResponseShapeSchema,
});

export const apiSchemaManifestResponseSchema = z.object({
  version: z.literal(1),
  routes: z.array(apiSchemaManifestRouteSchema),
});

export type MastraPackage = z.infer<typeof mastraPackageSchema>;
export type SystemPackagesResponse = z.infer<typeof systemPackagesResponseSchema>;
